--[[
接口描述：返回游戏res_key对应的资源信息
返回：table，资源位置信息
--]]
function M.get_game_res_location()
    if EU.is_text_empty(res_key) then
        return nil, EC.BASE_API_COMMON_ERROR.CODE_INVALID_PARAMETER, "res_key is invalid"
    end
    return ER.get_res_location_with_namespace(M.NAMESPACES.QZ_PATCH, res_key)
end

--[[
@param res_key 资源标识
@return table类型，返回资源标识对应的状态信息
--]]
function M.get_res_state(_res_key)
    local inner_res_key = _res_key or res_key
    local res_state_info = ER.get_res_state(M.NAMESPACES.QZ_PATCH, inner_res_key)
    local simple_res_state_info = ER.get_simple_res_state(res_state_info)
    return simple_res_state_info
end

