--[[
单独下载一个url文件的接口
@param _res_key 必传，string, 资源标识
@param res_version 必传，string, 资源版本
@param file_path_list: 文件列表，array
        path: 必传、string, 相对base_url路径，完整路径 base_url + folder + path, 注意path包含文件名和路径
        name: 不传会解析url后缀的文件名作为下载目标文件名
        dest_path: 相对路径，相对storage_type下的路径，如果没有传会下载到ejoy 默认路径，该路径会在下载状态中获取，也可以通过task的get_download_state获取
        md5: 用于校验文件下载完整性；
        size: 大小
        tag: 任务标签，用于标记一个任务。如果不传则SDK内部自己生成唯一ID
@param opts：
        max_retry_times：可选，重试次数。不传默认为3次
        storage_type: default is {@link M.STORAGE_TYPE.INTERNAL_APP_PRIVATE}
        enable_download_range: 传true or false，默认false，传true代表开启断点续传
@param complete_cb: 必传，function类型，下载完成回调，回调内容如下：
        @param succ, bool, 是否成功，true: 成功，false: 失败
        @param ... 可变参数，如果succ为true，则该可变参数为state_obj，如果为false，则该可变参数为code, msg
@param state_listener: 可选， function类型，下载状态监听，通知当前的下载状态信息，进度发生变化时也会触发该通知
@param progress_listener：可选，function类型，下载进度监听，受opts.progress_notify_interval_millis的影响，根据该设置间隔通知进度变化
--]]
function M.download_res_files(_res_key, res_version, file_path_list, opts, complete_cb, state_listener, progress_listener)
    ER.download_res_files(M.NAMESPACES.QZ_PATCH, _res_key, res_version, file_path_list, opts, complete_cb, state_listener, progress_listener)
end

--[[
@param storage_type ,见{@link M.STORAGE_TYPE}
--]]
function M.get_storage_path_by_type(storage_type)
    storage_type = storage_type or M.STORAGE_TYPE.INTERNAL_APP_PRIVATE
    local storage_type_path_base = ERB.static_get_storage_path_by_type(storage_type)
    local storage_dir = E.Utils.trim_end(storage_type_path_base, "/")
    return storage_dir
end

--[[
清理资源
@param res_key 资源标识
]]
function M.repair(_res_key)
    local inner_res_key = _res_key or res_key
    ER.publish_using_res_version(M.NAMESPACES.QZ_PATCH, inner_res_key, nil, nil, nil)
end

function M.publish_using_res_version(_res_key, version)
    ER.publish_using_res_version(M.NAMESPACES.QZ_PATCH, _res_key, version, nil, M.RES_TYPE.QZ_PATCH)
end

return M